package rpg.engine.script;
import java.util.*;
public final class Lexer {private final String s;private int p,line=1,col=1;public Lexer(String s){this.s=s;}private char c(){return p<s.length()?s.charAt(p):'\0';}private char next(){char x=c();p++;if(x=='\n'){line++;col=1;}else col++;return x;}public List<Token> lex(){var a=new ArrayList<Token>();while(true){skip();int l=line,k=col;char x=c();if(x=='\0'){a.add(new Token(Token.Type.EOF,"",l,k));return a;}if(Character.isLetter(x)||x=='_'){StringBuilder b=new StringBuilder();while(Character.isLetterOrDigit(c())||c()=='_')b.append(next());String t=b.toString();var ty=switch(t){case"let"->Token.Type.LET;case"if"->Token.Type.IF;case"else"->Token.Type.ELSE;case"return"->Token.Type.RETURN;case"function"->Token.Type.FUNCTION;case"true"->Token.Type.TRUE;case"false"->Token.Type.FALSE;case"nil"->Token.Type.NIL;default->Token.Type.IDENT;};a.add(new Token(ty,t,l,k));continue;}if(Character.isDigit(x)){StringBuilder b=new StringBuilder();while(Character.isDigit(c())||c()=='.')b.append(next());a.add(new Token(Token.Type.NUMBER,b.toString(),l,k));continue;}if(x=='"'||x=='\''){char q=next();StringBuilder b=new StringBuilder();while(c()!=q&&c()!='\0'){if(c()=='\\'){next();char z=next();b.append(switch(z){case'n'->'\n';case't'->'\t';default->z;});}else b.append(next());}if(c()==q)next();a.add(new Token(Token.Type.STRING,b.toString(),l,k));continue;}Token.Type ty=switch(x){case'('->Token.Type.LP;case')'->Token.Type.RP;case'{'->Token.Type.LBRACE;case'}'->Token.Type.RBRACE;case','->Token.Type.COMMA;case'.'->Token.Type.DOT;case'='->Token.Type.ASSIGN;case'+'->Token.Type.PLUS;case'-'->Token.Type.MINUS;case'*'->Token.Type.STAR;case'/'->Token.Type.SLASH;case';'->Token.Type.SEMICOLON;case'<'->Token.Type.LT;case'>'->Token.Type.GT;default->null;};if(ty==Token.Type.ASSIGN&&c2()=='='){next();ty=Token.Type.EQ;}else if(ty==Token.Type.LT&&c2()=='='){next();ty=Token.Type.LE;}else if(ty==Token.Type.GT&&c2()=='='){next();ty=Token.Type.GE;}else if(x=='!'&&c2()=='='){next();ty=Token.Type.NE;}if(ty==null)throw error("unexpected character "+x);next();a.add(new Token(ty,String.valueOf(x),l,k));}}private char c2(){return p+1<s.length()?s.charAt(p+1):'\0';}private void skip(){while(true){while(Character.isWhitespace(c()))next();if(c()=='-'&&c2()=='-'){while(c()!='\n'&&c()!='\0')next();}else break;}}private RuntimeException error(String m){return new IllegalArgumentException("script "+line+":"+col+": "+m);}}
